package org.apache.commons.text.similarity;

import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class LevenshteinDetailedDistance_ESTest_test18 extends LevenshteinDetailedDistance_ESTest_scaffolding {

    /**
     * Verifies the unbounded Levenshtein distance between two sequences that share
     * a single matching character but differ in length.
     *
     * <p>The sequences are built from char arrays so that every unset position is the
     * NUL character ('�'):</p>
     * <ul>
     *   <li>left  (length 8): 'S' at indexes 0, 2 and 5, NUL elsewhere</li>
     *   <li>right (length 7): 'S' at index 3, NUL elsewhere</li>
     * </ul>
     *
     * <p>Converting left into right needs 3 edits, none of which is a substitution.</p>
     */
    @Test(timeout = 4000)
    public void testDistanceWithDifferentLengthsHasNoSubstitutions() throws Throwable {
        char[] leftChars = new char[8];
        leftChars[0] = 'S';
        leftChars[2] = 'S';
        leftChars[5] = 'S';

        char[] rightChars = new char[7];
        rightChars[3] = 'S';

        CharBuffer left = CharBuffer.wrap(leftChars);
        CharBuffer right = CharBuffer.wrap(rightChars);

        LevenshteinDetailedDistance distance = new LevenshteinDetailedDistance();
        LevenshteinResults results = distance.apply((CharSequence) left, (CharSequence) right);

        assertEquals(3, (int) results.getDistance());
        assertEquals(0, (int) results.getSubstituteCount());
    }
}
